{
  "version": 3,
  "sources": ["src/app/usuario/dashboard/dashboard.component.css"],
  "sourcesContent": [".dashboard-container {\n  padding: 20px;\n  height: 100%;\n  overflow-y: auto;\n}\n\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n  gap: 20px;\n  margin-bottom: 30px;\n}\n\n.stat-card {\n  background: white;\n  border-radius: 12px;\n  padding: 25px;\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n  transition: transform 0.3s ease;\n}\n\n.stat-card:hover {\n  transform: translateY(-2px);\n}\n\n.stat-icon {\n  width: 60px;\n  height: 60px;\n  border-radius: 12px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 24px;\n  color: white;\n}\n\n.stat-icon.pending { background: #f39c12; }\n.stat-icon.processing { background: #3498db; }\n.stat-icon.completed { background: #27ae60; }\n.stat-icon.total { background: #9b59b6; }\n\n.stat-content h3 {\n  font-size: 32px;\n  font-weight: 700;\n  margin: 0;\n  color: #2c3e50;\n}\n\n.stat-content p {\n  font-size: 14px;\n  color: #7f8c8d;\n  margin: 4px 0 0 0;\n}\n\n.content-grid {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 20px;\n  margin-bottom: 30px;\n}\n\n.card {\n  background: white;\n  border-radius: 12px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n  overflow: hidden;\n}\n\n.card-header {\n  padding: 20px 25px;\n  border-bottom: 1px solid #f1f2f6;\n  background: #fafbfc;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.card-header h3 {\n  margin: 0;\n  font-size: 18px;\n  font-weight: 600;\n  color: #2c3e50;\n}\n\n.btn-link {\n  background: none;\n  border: none;\n  color: #667eea;\n  font-size: 14px;\n  cursor: pointer;\n  font-weight: 500;\n  transition: color 0.3s ease;\n}\n\n.btn-link:hover {\n  color: #5a67d8;\n}\n\n.card-content {\n  padding: 25px;\n}\n\n.activity-list-container {\n  position: relative;\n}\n\n.activity-list {\n  max-height: 400px;\n  overflow-y: auto;\n  scrollbar-width: thin;\n  scrollbar-color: #cbd5e0 #f7fafc;\n}\n\n.activity-list::-webkit-scrollbar {\n  width: 6px;\n}\n\n.activity-list::-webkit-scrollbar-track {\n  background: #f7fafc;\n  border-radius: 3px;\n}\n\n.activity-list::-webkit-scrollbar-thumb {\n  background: #cbd5e0;\n  border-radius: 3px;\n}\n\n.activity-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 15px;\n  margin-bottom: 15px;\n}\n\n.activity-item:last-child {\n  margin-bottom: 0;\n}\n\n.activity-icon {\n  width: 40px;\n  height: 40px;\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 16px;\n  color: white;\n  flex-shrink: 0;\n}\n\n.activity-icon.tramite { background: #3498db; }\n.activity-icon.notification { background: #e74c3c; }\n.activity-icon.user { background: #27ae60; }\n.activity-icon.empty { background: #e2e8f0; color: #a0aec0; }\n.activity-icon.loading { background: #f0f0f0; color: #999; }\n\n.activity-content {\n  flex: 1;\n}\n\n.activity-content p {\n  margin: 0 0 4px 0;\n  font-size: 14px;\n  color: #2c3e50;\n  line-height: 1.4;\n}\n\n.activity-meta {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 4px;\n}\n\n.activity-status {\n  padding: 2px 8px;\n  border-radius: 12px;\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.activity-status.status-completed {\n  background: #d4edda;\n  color: #155724;\n}\n\n.activity-status.status-pending {\n  background: #fff3cd;\n  color: #856404;\n}\n\n.activity-status.status-rejected {\n  background: #f8d7da;\n  color: #721c24;\n}\n\n.activity-time {\n  font-size: 12px;\n  color: #7f8c8d;\n}\n\n.actions-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 15px;\n}\n\n.action-btn {\n  background: #f8f9fa;\n  border: 2px solid #e9ecef;\n  border-radius: 10px;\n  padding: 20px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 10px;\n  cursor: pointer;\n  transition: all 0.3s ease;\n}\n\n.action-btn:hover {\n  background: #667eea;\n  border-color: #667eea;\n  color: white;\n  transform: translateY(-2px);\n}\n\n.action-btn i {\n  font-size: 24px;\n  color: #667eea;\n  transition: color 0.3s ease;\n}\n\n.action-btn:hover i {\n  color: white;\n}\n\n.action-btn span {\n  font-size: 12px;\n  font-weight: 600;\n  color: #2c3e50;\n  transition: color 0.3s ease;\n}\n\n.action-btn:hover span {\n  color: white;\n}\n\n.my-recent-tramites {\n  margin-top: 30px;\n}\n\n.tramites-list {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n}\n\n.tramite-item {\n  padding: 15px;\n  background: #f8f9fa;\n  border-radius: 8px;\n  border-left: 4px solid #667eea;\n}\n\n.tramite-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 8px;\n}\n\n.tramite-codigo {\n  font-size: 12px;\n  font-weight: 600;\n  color: #667eea;\n}\n\n.estado-badge {\n  padding: 4px 10px;\n  border-radius: 12px;\n  font-size: 11px;\n  font-weight: 600;\n  text-transform: uppercase;\n}\n\n.estado-badge.en-revision {\n  background: #fff3cd;\n  color: #856404;\n}\n\n.estado-badge.en-proceso {\n  background: #cfe2ff;\n  color: #004085;\n}\n\n.estado-badge.finalizado {\n  background: #d4edda;\n  color: #155724;\n}\n\n.estado-badge.observado {\n  background: #f8d7da;\n  color: #721c24;\n}\n\n.tramite-title {\n  font-weight: 600;\n  color: #2c3e50;\n  margin-bottom: 8px;\n}\n\n.tramite-meta {\n  display: flex;\n  gap: 20px;\n  font-size: 12px;\n  color: #7f8c8d;\n  margin-bottom: 10px;\n}\n\n.tramite-meta i {\n  margin-right: 5px;\n  color: #a0aec0;\n}\n\n.tramite-progress {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 10px;\n}\n\n.progress-bar {\n  flex: 1;\n  height: 8px;\n  background: #e2e8f0;\n  border-radius: 4px;\n  overflow: hidden;\n}\n\n.progress-fill {\n  height: 100%;\n  background: linear-gradient(90deg, #667eea, #9f7aea);\n  transition: width 0.3s ease;\n}\n\n.progress-text {\n  font-size: 12px;\n  font-weight: 600;\n  color: #667eea;\n  min-width: 40px;\n  text-align: right;\n}\n\n.empty-state .activity-content p {\n  color: #a0aec0;\n  font-style: italic;\n}\n\n.loading-item .activity-content p {\n  color: #999;\n}\n\n@media (max-width: 768px) {\n  .dashboard-container {\n    padding: 15px;\n  }\n\n  .stats-grid {\n    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n    gap: 15px;\n  }\n\n  .content-grid {\n    grid-template-columns: 1fr;\n    gap: 15px;\n  }\n\n  .actions-grid {\n    grid-template-columns: repeat(3, 1fr);\n    gap: 10px;\n  }\n\n  .action-btn {\n    padding: 15px 10px;\n  }\n}\n\n@media (max-width: 480px) {\n  .stats-grid {\n    grid-template-columns: 1fr;\n    gap: 10px;\n  }\n\n  .actions-grid {\n    grid-template-columns: 1fr;\n    gap: 10px;\n  }\n\n  .action-btn {\n    flex-direction: row;\n    justify-content: flex-start;\n    gap: 15px;\n    padding: 15px;\n  }\n\n  .action-btn i {\n    font-size: 20px;\n  }\n}\n"],
